112	/**
113	 * @see {parsePositionSizeOption} and also accept a string preset.
114	 * @see {PositionSizeOption}
115	 */
116	export function parsePositionOption(option: unknown, percentBase: number, percentOffset?: number): number {
117	    switch (option) {
118	        case 'center':
119	        case 'middle':
120	            option = '50%';
121	            break;
122	        case 'left':
123	        case 'top':
124	            option = '0%';
125	            break;
126	        case 'right':
127	        case 'bottom':
128	            option = '100%';
129	            break;
130	    }
131	    return parsePositionSizeOption(option, percentBase, percentOffset);
132	}
