134	/**
135	 * Accept number, or numeric stirng (`'123'`), or percentage ('100%'), as x/y/width/height pixel number.
136	 * If null/undefined or invalid, return NaN.
137	 * (But allow JS type coercion (`+option`) due to backward compatibility)
138	 * @see {PositionSizeOption}
139	 */
140	export function parsePositionSizeOption(option: unknown, percentBase: number, percentOffset?: number): number {
141	    if (zrUtil.isString(option)) {
142	        if (_trim(option).match(/%$/)) {
143	            return parseFloat(option) / 100 * percentBase + (percentOffset || 0);
144	        }
145	        return parseFloat(option);
146	    }
147	    // Allow flexible input due to backward compatibility.
148	    return option == null ? NaN : +option;
149	}
