151	/**
152	 * (1) Fix rounding error of float numbers.
153	 * (2) Support return string to avoid scientific notation like '3.5e-7'.
154	 */
155	export function round(x: number | string, precision?: number): number;
156	export function round(x: number | string, precision: number, returnStr: false): number;
157	export function round(x: number | string, precision: number, returnStr: true): string;
158	export function round(x: number | string, precision?: number, returnStr?: boolean): string | number {
159	    if (precision == null) {
160	        precision = 10;
161	    }
162	    // Avoid range error
163	    precision = Math.min(Math.max(0, precision), ROUND_SUPPORTED_PRECISION_MAX);
164	    // PENDING: 1.005.toFixed(2) is '1.00' rather than '1.01'
165	    x = (+x).toFixed(precision);
166	    return (returnStr ? x : +x);
167	}
