169	/**
170	 * Inplacd asc sort arr.
171	 * The input arr will be modified.
172	 */
173	export function asc<T extends number[]>(arr: T): T {
174	    arr.sort(function (a, b) {
175	        return a - b;
176	    });
177	    return arr;
178	}
