180	/**
181	 * Get precision.
182	 */
183	export function getPrecision(val: string | number): number {
184	    val = +val;
185	    if (isNaN(val)) {
186	        return 0;
187	    }
188	
189	    // It is much faster than methods converting number to string as follows
190	    //      let tmp = val.toString();
191	    //      return tmp.length - 1 - tmp.indexOf('.');
192	    // especially when precision is low
193	    // Notice:
194	    // (1) If the loop count is over about 20, it is slower than `getPrecisionSafe`.
195	    //     (see https://jsbench.me/2vkpcekkvw/1)
196	    // (2) If the val is less than for example 1e-15, the result may be incorrect.
197	    //     (see test/ut/spec/util/number.test.ts `getPrecision_equal_random`)
198	    if (val > 1e-14) {
199	        let e = 1;
200	        for (let i = 0; i < 15; i++, e *= 10) {
201	            if (Math.round(val * e) / e === val) {
202	                return i;
203	            }
204	        }
205	    }
206	
207	    return getPrecisionSafe(val);
208	}
209	
210	/**
211	 * Get precision with slow but safe method
212	 */
213	export function getPrecisionSafe(val: string | number): number {
214	    // toLowerCase for: '3.4E-12'
215	    const str = val.toString().toLowerCase();
216	
217	    // Consider scientific notation: '3.4e-12' '3.4e+12'
218	    const eIndex = str.indexOf('e');
219	    const exp = eIndex > 0 ? +str.slice(eIndex + 1) : 0;
220	    const significandPartLen = eIndex > 0 ? eIndex : str.length;
221	    const dotIndex = str.indexOf('.');
222	    const decimalPartLen = dotIndex < 0 ? 0 : significandPartLen - 1 - dotIndex;
223	    return Math.max(0, decimalPartLen - exp);
224	}
