226	/**
227	 * Minimal dicernible data precisioin according to a single pixel.
228	 */
229	export function getPixelPrecision(dataExtent: [number, number], pixelExtent: [number, number]): number {
230	    const log = Math.log;
231	    const LN10 = Math.LN10;
232	    const dataQuantity = Math.floor(log(dataExtent[1] - dataExtent[0]) / LN10);
233	    const sizeQuantity = Math.round(log(mathAbs(pixelExtent[1] - pixelExtent[0])) / LN10);
234	    // toFixed() digits argument must be between 0 and 20.
235	    const precision = Math.min(Math.max(-dataQuantity + sizeQuantity, 0), 20);
236	    return !isFinite(precision) ? 20 : precision;
237	}
