536	type IntervalItem = {
537	    interval: [number, number]
538	    close: [0 | 1, 0 | 1]
539	};
540	/**
541	 * Order intervals asc, and split them when overlap.
542	 * expect(numberUtil.reformIntervals([
543	 *     {interval: [18, 62], close: [1, 1]},
544	 *     {interval: [-Infinity, -70], close: [0, 0]},
545	 *     {interval: [-70, -26], close: [1, 1]},
546	 *     {interval: [-26, 18], close: [1, 1]},
547	 *     {interval: [62, 150], close: [1, 1]},
548	 *     {interval: [106, 150], close: [1, 1]},
549	 *     {interval: [150, Infinity], close: [0, 0]}
550	 * ])).toEqual([
551	 *     {interval: [-Infinity, -70], close: [0, 0]},
552	 *     {interval: [-70, -26], close: [1, 1]},
553	 *     {interval: [-26, 18], close: [0, 1]},
554	 *     {interval: [18, 62], close: [0, 1]},
555	 *     {interval: [62, 150], close: [0, 1]},
556	 *     {interval: [150, Infinity], close: [0, 0]}
557	 * ]);
558	 * @param list, where `close` mean open or close
559	 *        of the interval, and Infinity can be used.
560	 * @return The origin list, which has been reformed.
561	 */
562	export function reformIntervals(list: IntervalItem[]): IntervalItem[] {
563	    list.sort(function (a, b) {
564	        return littleThan(a, b, 0) ? -1 : 1;
565	    });
566	
567	    let curr = -Infinity;
568	    let currClose = 1;
569	    for (let i = 0; i < list.length;) {
570	        const interval = list[i].interval;
571	        const close = list[i].close;
572	
573	        for (let lg = 0; lg < 2; lg++) {
574	            if (interval[lg] <= curr) {
575	                interval[lg] = curr;
576	                close[lg] = (!lg ? 1 - currClose : 1) as 0 | 1;
577	            }
578	            curr = interval[lg];
579	            currClose = close[lg];
580	        }
581	
582	        if (interval[0] === interval[1] && close[0] * close[1] !== 1) {
583	            list.splice(i, 1);
584	        }
585	        else {
586	            i++;
587	        }
588	    }
589	
590	    return list;
591	
592	    function littleThan(a: IntervalItem, b: IntervalItem, lg: number): boolean {
593	        return a.interval[lg] < b.interval[lg]
594	            || (
595	                a.interval[lg] === b.interval[lg]
596	                && (
597	                    (a.close[lg] - b.close[lg] === (!lg ? 1 : -1))
598	                    || (!lg && littleThan(a, b, 1))
599	                )
600	            );
601	    }
602	}
