604	/**
605	 * [Numeric is defined as]:
606	 *     `parseFloat(val) == val`
607	 * For example:
608	 * numeric:
609	 *     typeof number except NaN, '-123', '123', '2e3', '-2e3', '011', 'Infinity', Infinity,
610	 *     and they rounded by white-spaces or line-terminal like ' -123 \n ' (see es spec)
611	 * not-numeric:
612	 *     null, undefined, [], {}, true, false, 'NaN', NaN, '123ab',
613	 *     empty string, string with only white-spaces or line-terminal (see es spec),
614	 *     0x12, '0x12', '-0x12', 012, '012', '-012',
615	 *     non-string, ...
616	 *
617	 * @test See full test cases in `test/ut/spec/util/number.js`.
618	 * @return Must be a typeof number. If not numeric, return NaN.
619	 */
620	export function numericToNumber(val: unknown): number {
621	    const valFloat = parseFloat(val as string);
622	    return (
623	        valFloat == val // eslint-disable-line eqeqeq
624	        && (valFloat !== 0 || !zrUtil.isString(val) || val.indexOf('x') <= 0) // For case ' 0x0 '.
625	    ) ? valFloat : NaN;
626	}
627	
628	/**
629	 * Definition of "numeric": see `numericToNumber`.
630	 */
631	export function isNumeric(val: unknown): val is number {
632	    return !isNaN(numericToNumber(val));
633	}
634	
635	/**
636	 * Use random base to prevent users hard code depending on
637	 * this auto generated marker id.
638	 * @return An positive integer.
639	 */
640	export function getRandomIdBase(): number {
641	    return Math.round(Math.random() * 9);
642	}
643	
644	/**
645	 * Get the greatest common divisor.
646	 *
647	 * @param {number} a one number
648	 * @param {number} b the other number
649	 */
650	export function getGreatestCommonDividor(a: number, b: number): number {
651	    if (b === 0) {
652	        return a;
653	    }
654	    return getGreatestCommonDividor(b, a % b);
655	}
656	
657	/**
658	 * Get the least common multiple.
659	 *
660	 * @param {number} a one number
661	 * @param {number} b the other number
662	 */
663	export function getLeastCommonMultiple(a: number, b: number) {
664	    if (a == null) {
665	        return b;
666	    }
667	    if (b == null) {
668	        return a;
669	    }
670	    return a * b / getGreatestCommonDividor(a, b);
671	}
