20	import {getPrecision, round, nice, quantityExponent} from '../util/number';
21	import IntervalScale from './Interval';
22	import LogScale from './Log';
23	import type Scale from './Scale';
24	import { bind } from 'zrender/src/core/util';
25	import type { ScaleBreakContext } from './break';
26	
27	type intervalScaleNiceTicksResult = {
28	    interval: number,
29	    intervalPrecision: number,
30	    niceTickExtent: [number, number]
31	};
32	
33	export function isValueNice(val: number) {
34	    const exp10 = Math.pow(10, quantityExponent(Math.abs(val)));
35	    const f = Math.abs(val / exp10);
36	    return f === 0
37	        || f === 1
38	        || f === 2
39	        || f === 3
40	        || f === 5;
41	}
42	
43	export function isIntervalOrLogScale(scale: Scale): scale is LogScale | IntervalScale {
44	    return scale.type === 'interval' || scale.type === 'log';
45	}
46	/**
47	 * @param extent Both extent[0] and extent[1] should be valid number.
48	 *               Should be extent[0] < extent[1].
49	 * @param splitNumber splitNumber should be >= 1.
50	 */
51	export function intervalScaleNiceTicks(
52	    extent: [number, number],
53	    spanWithBreaks: number,
54	    splitNumber: number,
55	    minInterval?: number,
56	    maxInterval?: number
57	): intervalScaleNiceTicksResult {
58	
59	    const result = {} as intervalScaleNiceTicksResult;
60	
61	    let interval = result.interval = nice(spanWithBreaks / splitNumber, true);
62	    if (minInterval != null && interval < minInterval) {
63	        interval = result.interval = minInterval;
64	    }
65	    if (maxInterval != null && interval > maxInterval) {
66	        interval = result.interval = maxInterval;
67	    }
68	    // Tow more digital for tick.
69	    const precision = result.intervalPrecision = getIntervalPrecision(interval);
70	    // Niced extent inside original extent
71	    const niceTickExtent = result.niceTickExtent = [
72	        round(Math.ceil(extent[0] / interval) * interval, precision),
73	        round(Math.floor(extent[1] / interval) * interval, precision)
74	    ];
75	
76	    fixExtent(niceTickExtent, extent);
77	
78	    return result;
79	}
80	
81	export function increaseInterval(interval: number) {
82	    const exp10 = Math.pow(10, quantityExponent(interval));
83	    // Increase interval
84	    let f = interval / exp10;
85	    if (!f) {
86	        f = 1;
87	    }
88	    else if (f === 2) {
89	        f = 3;
90	    }
91	    else if (f === 3) {
92	        f = 5;
93	    }
94	    else { // f is 1 or 5
95	        f *= 2;
96	    }
97	    return round(f * exp10);
98	}
99	
100	/**
101	 * @return interval precision
102	 */
103	export function getIntervalPrecision(interval: number): number {
104	    // Tow more digital for tick.
105	    return getPrecision(interval) + 2;
106	}
107	
108	function clamp(
109	    niceTickExtent: [number, number], idx: number, extent: [number, number]
110	): void {
111	    niceTickExtent[idx] = Math.max(Math.min(niceTickExtent[idx], extent[1]), extent[0]);
112	}
113	
114	// In some cases (e.g., splitNumber is 1), niceTickExtent may be out of extent.
115	export function fixExtent(
116	    niceTickExtent: [number, number], extent: [number, number]
117	): void {
118	    !isFinite(niceTickExtent[0]) && (niceTickExtent[0] = extent[0]);
119	    !isFinite(niceTickExtent[1]) && (niceTickExtent[1] = extent[1]);
120	    clamp(niceTickExtent, 0, extent);
121	    clamp(niceTickExtent, 1, extent);
122	    if (niceTickExtent[0] > niceTickExtent[1]) {
123	        niceTickExtent[0] = niceTickExtent[1];
124	    }
125	}
126	
127	export function contain(val: number, extent: [number, number]): boolean {
128	    return val >= extent[0] && val <= extent[1];
129	}
130	
131	export class ScaleCalculator {
132	
133	    normalize: (val: number, extent: [number, number]) => number = normalize;
134	    scale: (val: number, extent: [number, number]) => number = scale;
135	
136	    updateMethods(brkCtx: ScaleBreakContext) {
137	        if (brkCtx.hasBreaks()) {
138	            this.normalize = bind(brkCtx.normalize, brkCtx);
139	            this.scale = bind(brkCtx.scale, brkCtx);
140	        }
141	        else {
142	            this.normalize = normalize;
143	            this.scale = scale;
144	        }
145	    }
146	}
147	
148	function normalize(
149	    val: number,
150	    extent: [number, number],
151	    // Dont use optional arguments for performance consideration here.
152	): number {
153	    if (extent[1] === extent[0]) {
154	        return 0.5;
155	    }
156	    return (val - extent[0]) / (extent[1] - extent[0]);
157	}
158	
159	function scale(
160	    val: number,
161	    extent: [number, number],
162	): number {
163	    return val * (extent[1] - extent[0]) + extent[0];
164	}
165	
166	export function logTransform(base: number, extent: number[], noClampNegative?: boolean): [number, number] {
167	    const loggedBase = Math.log(base);
168	    return [
169	        // log(negative) is NaN, so safe guard here.
170	        // PENDING: But even getting a -Infinity still does not make sense in extent.
171	        //  Just keep it as is, getting a NaN to make some previous cases works by coincidence.
172	        Math.log(noClampNegative ? extent[0] : Math.max(0, extent[0])) / loggedBase,
173	        Math.log(noClampNegative ? extent[1] : Math.max(0, extent[1])) / loggedBase
174	    ];
175	}
