21	import * as numberUtil from '../util/number';
22	import * as formatUtil from '../util/format';
23	import Scale, { ScaleGetTicksOpt, ScaleSettingDefault } from './Scale';
24	import * as helper from './helper';
25	import {ScaleTick, ParsedAxisBreakList, ScaleDataValue} from '../util/types';
26	import { getScaleBreakHelper } from './break';
27	
28	const roundNumber = numberUtil.round;
29	
30	class IntervalScale<SETTING extends ScaleSettingDefault = ScaleSettingDefault> extends Scale<SETTING> {
31	
32	    static type = 'interval';
33	    type = 'interval';
34	
35	    // Step is calculated in adjustExtent.
36	    protected _interval: number = 0;
37	    protected _niceExtent: [number, number];
38	    private _intervalPrecision: number = 2;
39	
40	
41	    parse(val: ScaleDataValue): number {
42	        // `Scale#parse` (and its overrids) are typically applied at the axis values input
43	        // in echarts option. e.g., `axis.min/max`, `dataZoom.min/max`, etc.
44	        // but `series.data` is not included, which uses `dataValueHelper.ts`#`parseDataValue`.
45	        // `Scale#parse` originally introduced in fb8c813215098b9d2458966229bb95c510883d5e
46	        // at 2016 for dataZoom start/end settings (See `parseAxisModelMinMax`).
47	        //
48	        // Historically `scale/Interval.ts` returns the input value directly. But numeric
49	        // values (such as a number-like string '123') effectively passed through here and
50	        // were involved in calculations, which was error-prone and inconsistent with the
51	        // declared TS return type. Previously such issues are fixed separately in different
52	        // places case by case (such as #2475).
53	        //
54	        // Now, we perform actual parse to ensure its `number` type here. The parsing rule
55	        // follows the series data parsing rule (`dataValueHelper.ts`#`parseDataValue`)
56	        // and maintains compatibility as much as possible (thus a more strict parsing
57	        // `number.ts`#`numericToNumber` is not used here.)
58	        //
59	        // FIXME: `ScaleDataValue` also need to be modified to include numeric string type,
60	        //  since it effectively does.
61	        return (val == null || val === '')
62	            ? NaN
63	            // If string (like '-'), using '+' parse to NaN
64	            // If object, also parse to NaN
65	            : Number(val);
66	    }
67	
68	    contain(val: number): boolean {
69	        return helper.contain(val, this._extent);
70	    }
71	
72	    normalize(val: number): number {
73	        return this._calculator.normalize(val, this._extent);
74	    }
75	
76	    scale(val: number): number {
77	        return this._calculator.scale(val, this._extent);
78	    }
79	
80	    getInterval(): number {
81	        return this._interval;
82	    }
83	
84	    setInterval(interval: number): void {
85	        this._interval = interval;
86	        // Dropped auto calculated niceExtent and use user-set extent.
87	        // We assume user wants to set both interval, min, max to get a better result.
88	        this._niceExtent = this._extent.slice() as [number, number];
89	
90	        this._intervalPrecision = helper.getIntervalPrecision(interval);
91	    }
92	
93	    /**
94	     * @override
95	     */
96	    getTicks(opt?: ScaleGetTicksOpt): ScaleTick[] {
97	        opt = opt || {};
98	        const interval = this._interval;
99	        const extent = this._extent;
100	        const niceTickExtent = this._niceExtent;
101	        const intervalPrecision = this._intervalPrecision;
102	        const scaleBreakHelper = getScaleBreakHelper();
103	
104	        const ticks = [] as ScaleTick[];
105	        // If interval is 0, return [];
106	        if (!interval) {
107	            return ticks;
108	        }
109	
110	        if (opt.breakTicks === 'only_break' && scaleBreakHelper) {
111	            scaleBreakHelper.addBreaksToTicks(ticks, this._brkCtx!.breaks, this._extent);
112	            return ticks;
113	        }
114	
115	        // Consider this case: using dataZoom toolbox, zoom and zoom.
116	        const safeLimit = 10000;
117	
118	        if (extent[0] < niceTickExtent[0]) {
119	            if (opt.expandToNicedExtent) {
120	                ticks.push({
121	                    value: roundNumber(niceTickExtent[0] - interval, intervalPrecision)
122	                });
123	            }
124	            else {
125	                ticks.push({
126	                    value: extent[0]
127	                });
128	            }
129	        }
130	
131	        const estimateNiceMultiple = (tickVal: number, targetTick: number) => {
132	            return Math.round((targetTick - tickVal) / interval);
133	        };
134	
135	        let tick = niceTickExtent[0];
136	        while (tick <= niceTickExtent[1]) {
137	            ticks.push({
138	                value: tick
139	            });
140	
141	            // Avoid rounding error
142	            tick = roundNumber(tick + interval, intervalPrecision);
143	            if (this._brkCtx) {
144	                const moreMultiple = this._brkCtx.calcNiceTickMultiple(tick, estimateNiceMultiple);
145	                if (moreMultiple >= 0) {
146	                    tick = roundNumber(tick + moreMultiple * interval, intervalPrecision);
147	                }
148	            }
149	
150	            if (ticks.length > 0 && tick === ticks[ticks.length - 1].value) {
151	                // Consider out of safe float point, e.g.,
152	                // -3711126.9907707 + 2e-10 === -3711126.9907707
153	                break;
154	            }
155	            if (ticks.length > safeLimit) {
156	                return [];
157	            }
158	        }
159	        // Consider this case: the last item of ticks is smaller
160	        // than niceTickExtent[1] and niceTickExtent[1] === extent[1].
161	        const lastNiceTick = ticks.length ? ticks[ticks.length - 1].value : niceTickExtent[1];
162	        if (extent[1] > lastNiceTick) {
163	            if (opt.expandToNicedExtent) {
164	                ticks.push({
165	                    value: roundNumber(lastNiceTick + interval, intervalPrecision)
166	                });
167	            }
168	            else {
169	                ticks.push({
170	                    value: extent[1]
171	                });
172	            }
173	        }
174	
175	        if (scaleBreakHelper) {
176	            scaleBreakHelper.pruneTicksByBreak(
177	                opt.pruneByBreak,
178	                ticks,
179	                this._brkCtx!.breaks,
180	                item => item.value,
181	                this._interval,
182	                this._extent
183	            );
184	        }
185	        if (opt.breakTicks !== 'none' && scaleBreakHelper) {
186	            scaleBreakHelper.addBreaksToTicks(ticks, this._brkCtx!.breaks, this._extent);
187	        }
188	
189	        return ticks;
190	    }
191	
192	    getMinorTicks(splitNumber: number): number[][] {
193	        const ticks = this.getTicks({
194	            expandToNicedExtent: true,
195	        });
196	        // NOTE: In log-scale, do not support minor ticks when breaks exist.
197	        //  because currently log-scale minor ticks is calculated based on raw values
198	        //  rather than log-transformed value, due to an odd effect when breaks exist.
199	        const minorTicks = [];
200	        const extent = this.getExtent();
201	
202	        for (let i = 1; i < ticks.length; i++) {
203	            const nextTick = ticks[i];
204	            const prevTick = ticks[i - 1];
205	
206	            if (prevTick.break || nextTick.break) {
207	                // Do not build minor ticks to the adjacent ticks to breaks ticks,
208	                // since the interval might be irregular.
209	                continue;
210	            }
211	
212	            let count = 0;
213	            const minorTicksGroup = [];
214	            const interval = nextTick.value - prevTick.value;
215	            const minorInterval = interval / splitNumber;
216	
217	            while (count < splitNumber - 1) {
218	                const minorTick = roundNumber(prevTick.value + (count + 1) * minorInterval);
219	
220	                // For the first and last interval. The count may be less than splitNumber.
221	                if (minorTick > extent[0] && minorTick < extent[1]) {
222	                    minorTicksGroup.push(minorTick);
223	                }
224	                count++;
225	            }
226	
227	            const scaleBreakHelper = getScaleBreakHelper();
228	            scaleBreakHelper && scaleBreakHelper.pruneTicksByBreak(
229	                'auto',
230	                minorTicksGroup,
231	                this._getNonTransBreaks(),
232	                value => value,
233	                this._interval,
234	                extent
235	            );
236	            minorTicks.push(minorTicksGroup);
237	        }
238	
239	        return minorTicks;
240	    }
241	
242	    protected _getNonTransBreaks(): ParsedAxisBreakList {
243	        return this._brkCtx ? this._brkCtx.breaks : [];
244	    }
245	
246	    /**
247	     * @param opt.precision If 'auto', use nice presision.
248	     * @param opt.pad returns 1.50 but not 1.5 if precision is 2.
249	     */
250	    getLabel(
251	        data: ScaleTick,
252	        opt?: {
253	            precision?: 'auto' | number,
254	            pad?: boolean
255	        }
256	    ): string {
257	        if (data == null) {
258	            return '';
259	        }
260	
261	        let precision = opt && opt.precision;
262	
263	        if (precision == null) {
264	            precision = numberUtil.getPrecision(data.value) || 0;
265	        }
266	        else if (precision === 'auto') {
267	            // Should be more precise then tick.
268	            precision = this._intervalPrecision;
269	        }
270	
271	        // (1) If `precision` is set, 12.005 should be display as '12.00500'.
272	        // (2) Use roundNumber (toFixed) to avoid scientific notation like '3.5e-7'.
273	        const dataNum = roundNumber(data.value, precision as number, true);
274	
275	        return formatUtil.addCommas(dataNum);
276	    }
277	
278	    /**
279	     * @param splitNumber By default `5`.
280	     */
281	    calcNiceTicks(splitNumber?: number, minInterval?: number, maxInterval?: number): void {
282	        splitNumber = splitNumber || 5;
283	        let extent = this._extent.slice() as [number, number];
284	        let span = this._getExtentSpanWithBreaks();
285	        if (!isFinite(span)) {
286	            return;
287	        }
288	        // User may set axis min 0 and data are all negative
289	        // FIXME If it needs to reverse ?
290	        if (span < 0) {
291	            span = -span;
292	            extent.reverse();
293	            this._innerSetExtent(extent[0], extent[1]);
294	            extent = this._extent.slice() as [number, number];
295	        }
296	
297	        const result = helper.intervalScaleNiceTicks(
298	            extent, span, splitNumber, minInterval, maxInterval
299	        );
300	
301	        this._intervalPrecision = result.intervalPrecision;
302	        this._interval = result.interval;
303	        this._niceExtent = result.niceTickExtent;
304	    }
305	
306	    calcNiceExtent(opt: {
307	        splitNumber: number, // By default 5.
308	        fixMin?: boolean,
309	        fixMax?: boolean,
310	        minInterval?: number,
311	        maxInterval?: number
312	    }): void {
313	        let extent = this._extent.slice() as [number, number];
314	        // If extent start and end are same, expand them
315	        if (extent[0] === extent[1]) {
316	            if (extent[0] !== 0) {
317	                // Expand extent
318	                // Note that extents can be both negative. See #13154
319	                const expandSize = Math.abs(extent[0]);
320	                // In the fowllowing case
321	                //      Axis has been fixed max 100
322	                //      Plus data are all 100 and axis extent are [100, 100].
323	                // Extend to the both side will cause expanded max is larger than fixed max.
324	                // So only expand to the smaller side.
325	                if (!opt.fixMax) {
326	                    extent[1] += expandSize / 2;
327	                    extent[0] -= expandSize / 2;
328	                }
329	                else {
330	                    extent[0] -= expandSize / 2;
331	                }
332	            }
333	            else {
334	                extent[1] = 1;
335	            }
336	        }
337	        const span = extent[1] - extent[0];
338	        // If there are no data and extent are [Infinity, -Infinity]
339	        if (!isFinite(span)) {
340	            extent[0] = 0;
341	            extent[1] = 1;
342	        }
343	        this._innerSetExtent(extent[0], extent[1]);
344	        extent = this._extent.slice() as [number, number];
345	
346	        this.calcNiceTicks(opt.splitNumber, opt.minInterval, opt.maxInterval);
347	        const interval = this._interval;
348	
349	        if (!opt.fixMin) {
350	            extent[0] = roundNumber(Math.floor(extent[0] / interval) * interval);
351	        }
352	        if (!opt.fixMax) {
353	            extent[1] = roundNumber(Math.ceil(extent[1] / interval) * interval);
354	        }
355	        this._innerSetExtent(extent[0], extent[1]);
356	    }
357	
358	    setNiceExtent(min: number, max: number): void {
359	        this._niceExtent = [min, max];
360	    }
361	
362	}
363	
364	Scale.registerClass(IntervalScale);
365	
366	export default IntervalScale;
