28	export interface ScaleRawExtentResult {
29	    // `min`/`max` defines data available range, determined by
30	    // `dataMin`/`dataMax` and explicit specified min max related option.
31	    // The final extent will be based on the `min`/`max` and may be enlarge
32	    // a little (say, "nice strategy", e.g., niceScale, boundaryGap).
33	    // Ensure `min`/`max` be finite number or NaN here.
34	    // (not to be null/undefined) `NaN` means min/max axis is blank.
35	    readonly min: number;
36	    readonly max: number;
37	    // `minFixed`/`maxFixed` marks that `min`/`max` should be used
38	    // in the final extent without other "nice strategy".
39	    readonly minFixed: boolean;
40	    readonly maxFixed: boolean;
41	    // Mark that the axis should be blank.
42	    readonly isBlank: boolean;
43	}
44	
45	export class ScaleRawExtentInfo {
46	
47	    private _needCrossZero: boolean;
48	    private _isOrdinal: boolean;
49	    private _axisDataLen: number;
50	    private _boundaryGapInner: number[];
51	
52	    // Accurate raw value get from model.
53	    private _modelMinRaw: AxisBaseOption['min'];
54	    private _modelMaxRaw: AxisBaseOption['max'];
55	
56	    // Can be `finite number`/`null`/`undefined`/`NaN`
57	    private _modelMinNum: number;
58	    private _modelMaxNum: number;
59	
60	    // Range union by series data on this axis.
61	    // May be modified if data is filtered.
62	    private _dataMin: number;
63	    private _dataMax: number;
64	
65	    // Highest priority if specified.
66	    private _determinedMin: number;
67	    private _determinedMax: number;
68	
69	    // Make that the `rawExtentInfo` can not be modified any more.
70	    readonly frozen: boolean;
71	
72	
73	    constructor(
74	        scale: Scale,
75	        model: AxisBaseModel,
76	        // Usually: data extent from all series on this axis.
77	        originalExtent: number[]
78	    ) {
79	        this._prepareParams(scale, model, originalExtent);
80	    }
81	
82	    /**
83	     * Parameters depending on outside (like model, user callback)
84	     * are prepared and fixed here.
85	     */
86	    private _prepareParams(
87	        scale: Scale,
88	        model: AxisBaseModel,
89	        // Usually: data extent from all series on this axis.
90	        dataExtent: number[]
91	    ) {
92	        if (dataExtent[1] < dataExtent[0]) {
93	            dataExtent = [NaN, NaN];
94	        }
95	        this._dataMin = dataExtent[0];
96	        this._dataMax = dataExtent[1];
97	
98	        const isOrdinal = this._isOrdinal = scale.type === 'ordinal';
99	        this._needCrossZero = scale.type === 'interval' && model.getNeedCrossZero && model.getNeedCrossZero();
100	
101	        let axisMinValue = model.get('min', true);
102	        if (axisMinValue == null) {
103	            axisMinValue = model.get('startValue', true);
104	        }
105	        const modelMinRaw = this._modelMinRaw = axisMinValue;
106	        if (isFunction(modelMinRaw)) {
107	            // This callback always provides users the full data extent (before data is filtered).
108	            this._modelMinNum = parseAxisModelMinMax(scale, modelMinRaw({
109	                min: dataExtent[0],
110	                max: dataExtent[1]
111	            }));
112	        }
113	        else if (modelMinRaw !== 'dataMin') {
114	            this._modelMinNum = parseAxisModelMinMax(scale, modelMinRaw);
115	        }
116	
117	        const modelMaxRaw = this._modelMaxRaw = model.get('max', true);
118	        if (isFunction(modelMaxRaw)) {
119	            // This callback always provides users the full data extent (before data is filtered).
120	            this._modelMaxNum = parseAxisModelMinMax(scale, modelMaxRaw({
121	                min: dataExtent[0],
122	                max: dataExtent[1]
123	            }));
124	        }
125	        else if (modelMaxRaw !== 'dataMax') {
126	            this._modelMaxNum = parseAxisModelMinMax(scale, modelMaxRaw);
127	        }
128	
129	        if (isOrdinal) {
130	            // FIXME: there is a flaw here: if there is no "block" data processor like `dataZoom`,
131	            // and progressive rendering is using, here the category result might just only contain
132	            // the processed chunk rather than the entire result.
133	            this._axisDataLen = model.getCategories().length;
134	        }
135	        else {
136	            const boundaryGap = (model as AxisBaseModel<CategoryAxisBaseOption>).get('boundaryGap');
137	            const boundaryGapArr = isArray(boundaryGap)
138	                ? boundaryGap : [boundaryGap || 0, boundaryGap || 0];
139	
140	            if (typeof boundaryGapArr[0] === 'boolean' || typeof boundaryGapArr[1] === 'boolean') {
141	                if (__DEV__) {
142	                    console.warn('Boolean type for boundaryGap is only '
143	                        + 'allowed for ordinal axis. Please use string in '
144	                        + 'percentage instead, e.g., "20%". Currently, '
145	                        + 'boundaryGap is set to be 0.');
146	                }
147	                this._boundaryGapInner = [0, 0];
148	            }
149	            else {
150	                this._boundaryGapInner = [
151	                    parsePercent(boundaryGapArr[0], 1),
152	                    parsePercent(boundaryGapArr[1], 1)
153	                ];
154	            }
155	        }
156	    }
157	
158	    /**
159	     * Calculate extent by prepared parameters.
160	     * This method has no external dependency and can be called duplicatedly,
161	     * getting the same result.
162	     * If parameters changed, should call this method to recalcuate.
163	     */
164	    calculate(): ScaleRawExtentResult {
165	        // Notice: When min/max is not set (that is, when there are null/undefined,
166	        // which is the most common case), these cases should be ensured:
167	        // (1) For 'ordinal', show all axis.data.
168	        // (2) For others:
169	        //      + `boundaryGap` is applied (if min/max set, boundaryGap is
170	        //      disabled).
171	        //      + If `needCrossZero`, min/max should be zero, otherwise, min/max should
172	        //      be the result that originalExtent enlarged by boundaryGap.
173	        // (3) If no data, it should be ensured that `scale.setBlank` is set.
174	
175	        const isOrdinal = this._isOrdinal;
176	        const dataMin = this._dataMin;
177	        const dataMax = this._dataMax;
178	        const axisDataLen = this._axisDataLen;
179	        const boundaryGapInner = this._boundaryGapInner;
180	
181	        const span = !isOrdinal
182	            ? ((dataMax - dataMin) || Math.abs(dataMin))
183	            : null;
184	
185	        // Currently if a `'value'` axis model min is specified as 'dataMin'/'dataMax',
186	        // `boundaryGap` will not be used. It's the different from specifying as `null`/`undefined`.
187	        let min = this._modelMinRaw === 'dataMin' ? dataMin : this._modelMinNum;
188	        let max = this._modelMaxRaw === 'dataMax' ? dataMax : this._modelMaxNum;
189	
190	        // If `_modelMinNum`/`_modelMaxNum` is `null`/`undefined`, should not be fixed.
191	        let minFixed = min != null;
192	        let maxFixed = max != null;
193	
194	        if (min == null) {
195	            min = isOrdinal
196	                ? (axisDataLen ? 0 : NaN)
197	                : dataMin - boundaryGapInner[0] * span;
198	        }
199	        if (max == null) {
200	            max = isOrdinal
201	                ? (axisDataLen ? axisDataLen - 1 : NaN)
202	                : dataMax + boundaryGapInner[1] * span;
203	        }
204	
205	        (min == null || !isFinite(min)) && (min = NaN);
206	        (max == null || !isFinite(max)) && (max = NaN);
207	
208	        const isBlank = eqNaN(min)
209	            || eqNaN(max)
210	            || (isOrdinal && !axisDataLen);
211	
212	        // If data extent modified, need to recalculated to ensure cross zero.
213	        if (this._needCrossZero) {
214	            // Axis is over zero and min is not set
215	            if (min > 0 && max > 0 && !minFixed) {
216	                min = 0;
217	                // minFixed = true;
218	            }
219	            // Axis is under zero and max is not set
220	            if (min < 0 && max < 0 && !maxFixed) {
221	                max = 0;
222	                // maxFixed = true;
223	            }
224	            // PENDING:
225	            // When `needCrossZero` and all data is positive/negative, should it be ensured
226	            // that the results processed by boundaryGap are positive/negative?
227	            // If so, here `minFixed`/`maxFixed` need to be set.
228	        }
229	
230	        const determinedMin = this._determinedMin;
231	        const determinedMax = this._determinedMax;
232	        if (determinedMin != null) {
233	            min = determinedMin;
234	            minFixed = true;
235	        }
236	        if (determinedMax != null) {
237	            max = determinedMax;
238	            maxFixed = true;
239	        }
240	
241	        // Ensure min/max be finite number or NaN here. (not to be null/undefined)
242	        // `NaN` means min/max axis is blank.
243	        return {
244	            min: min,
245	            max: max,
246	            minFixed: minFixed,
247	            maxFixed: maxFixed,
248	            isBlank: isBlank
249	        };
250	    }
251	
252	    modifyDataMinMax(minMaxName: 'min' | 'max', val: number): void {
253	        if (__DEV__) {
254	            assert(!this.frozen);
255	        }
256	        this[DATA_MIN_MAX_ATTR[minMaxName]] = val;
257	    }
258	
259	    setDeterminedMinMax(minMaxName: 'min' | 'max', val: number): void {
260	        const attr = DETERMINED_MIN_MAX_ATTR[minMaxName];
261	        if (__DEV__) {
262	            assert(
263	                !this.frozen
264	                // Earse them usually means logic flaw.
265	                && (this[attr] == null)
266	            );
267	        }
268	        this[attr] = val;
269	    }
270	
271	    freeze() {
272	        // @ts-ignore
273	        this.frozen = true;
274	    }
275	}
276	
277	const DETERMINED_MIN_MAX_ATTR = { min: '_determinedMin', max: '_determinedMax' } as const;
278	const DATA_MIN_MAX_ATTR = { min: '_dataMin', max: '_dataMax' } as const;
279	
280	/**
281	 * Get scale min max and related info only depends on model settings.
282	 * This method can be called after coordinate system created.
283	 * For example, in data processing stage.
284	 *
285	 * Scale extent info probably be required multiple times during a workflow.
286	 * For example:
287	 * (1) `dataZoom` depends it to get the axis extent in "100%" state.
288	 * (2) `processor/extentCalculator` depends it to make sure whether axis extent is specified.
289	 * (3) `coordSys.update` use it to finally decide the scale extent.
290	 * But the callback of `min`/`max` should not be called multiple times.
291	 * The code below should not be implemented repeatedly either.
292	 * So we cache the result in the scale instance, which will be recreated at the beginning
293	 * of the workflow (because `scale` instance will be recreated each round of the workflow).
294	 */
295	export function ensureScaleRawExtentInfo(
296	    scale: Scale,
297	    model: AxisBaseModel,
298	    // Usually: data extent from all series on this axis.
299	    originalExtent: number[]
300	): ScaleRawExtentInfo {
301	
302	    // Do not permit to recreate.
303	    let rawExtentInfo = scale.rawExtentInfo;
304	    if (rawExtentInfo) {
305	        return rawExtentInfo;
306	    }
307	
308	    rawExtentInfo = new ScaleRawExtentInfo(scale, model, originalExtent);
309	    // @ts-ignore
310	    scale.rawExtentInfo = rawExtentInfo;
311	
312	    return rawExtentInfo;
313	}
314	
315	export function parseAxisModelMinMax(scale: Scale, minMax: ScaleDataValue): number {
316	    return minMax == null ? null
317	        : eqNaN(minMax) ? NaN
318	        : scale.parse(minMax);
319	}
